func (this *Gemini) ParseWsOrder(order any, optionalArgs ...any) any {
	//
	//     {
	//         "type": "accepted",
	//         "order_id": "134150423884",
	//         "event_id": "134150423886",
	//         "account_name": "primary",
	//         "client_order_id": "1659739406916",
	//         "api_session": "account-pnBFSS0XKGvDamX4uEIt",
	//         "symbol": "batbtc",
	//         "side": "sell",
	//         "order_type": "exchange limit",
	//         "timestamp": "1659739407",
	//         "timestampms": 1659739407576,
	//         "is_live": true,
	//         "is_cancelled": false,
	//         "is_hidden": false,
	//         "original_amount": "1",
	//         "price": "1",
	//         "socket_sequence": 139
	//     }
	//
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp any = this.SafeInteger(order, "timestampms")
	var status any = this.SafeString(order, "type")
	var marketId any = this.SafeString(order, "symbol")
	var typeId any = this.SafeString(order, "order_type")
	var behavior any = this.SafeString(order, "behavior")
	var timeInForce string = "GTC"
	var postOnly bool = false
	if ccxt.IsTrue(ccxt.IsEqual(behavior, "immediate-or-cancel")) {
		timeInForce = "IOC"
	} else if ccxt.IsTrue(ccxt.IsEqual(behavior, "fill-or-kill")) {
		timeInForce = "FOK"
	} else if ccxt.IsTrue(ccxt.IsEqual(behavior, "maker-or-cancel")) {
		timeInForce = "PO"
		postOnly = true
	}
	return this.SafeOrder(map[string]any{
		"id":                 this.SafeString(order, "order_id"),
		"clientOrderId":      this.SafeString(order, "client_order_id"),
		"info":               order,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             this.ParseWsOrderStatus(status),
		"symbol":             this.SafeSymbol(marketId, market),
		"type":               this.ParseWsOrderType(typeId),
		"timeInForce":        timeInForce,
		"postOnly":           postOnly,
		"side":               this.SafeString(order, "side"),
		"price":              this.SafeNumber(order, "price"),
		"stopPrice":          nil,
		"average":            this.SafeNumber(order, "avg_execution_price"),
		"cost":               nil,
		"amount":             this.SafeNumber(order, "original_amount"),
		"filled":             this.SafeNumber(order, "executed_amount"),
		"remaining":          this.SafeNumber(order, "remaining_amount"),
		"fee":                nil,
		"trades":             nil,
	}, market)
}
